class Solution {
    public int knightDialer(int n){
        int[][] next={
            {
                4,6
            },{
                6,8
            },{
                7,9
            },{
                4,8
            },{
                0,3,9
            },{
            },{
                0,1,7
            },{
                2,6
            },{
                1,3
            },{
                2,4
            }
        };
        long mod=1000000007L;
        long[] dp=new long[10];
        Arrays.fill(dp,1);
        for(int length=1;length<n;length++){
            long[] updated=new long[10];
            for(int from=0;from<10;from++)for(int to:next[from])updated[to]=(updated[to]+dp[from])%mod;
            dp=updated;
        }
        long answer=0;
        for(long ways:dp)answer=(answer+ways)%mod;
        return(int)answer;
    }
}

code.kotlin:
class Solution {
    fun knightDialer(n:Int):Int{
        val next=arrayOf(intArrayOf(4,6),intArrayOf(6,8),intArrayOf(7,9),intArrayOf(4,8),intArrayOf(0,3,9),intArrayOf(),intArrayOf(0,1,7),intArrayOf(2,6),intArrayOf(1,3),intArrayOf(2,4));
        val mod=1000000007L;
        var dp=LongArray(10){
            1
        };
        repeat(n-1){
            val updated=LongArray(10);
            for(from in 0..9)for(to in next[from])updated[to]=(updated[to]+dp[from])%mod;
            dp=updated
        };
        return (dp.sum()%mod).toInt()
    }
}

code.cpp:
class Solution {
    public: int knightDialer(int n){
        vector<vector<int>> next={
            {
                4,6
            },{
                6,8
            },{
                7,9
            },{
                4,8
            },{
                0,3,9
            },{
            },{
                0,1,7
            },{
                2,6
            },{
                1,3
            },{
                2,4
            }
        };
        const long long mod=1000000007;
        vector<long long> dp(10,1);
        for(int length=1;length<n;++length){
            vector<long long> updated(10);
            for(int from=0;from<10;++from)for(int to:next[from])updated[to]=(updated[to]+dp[from])%mod;
            dp.swap(updated);
        }
        return accumulate(dp.begin(),dp.end(),0LL)%mod;
    }
};
